param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop'; function Assert($ok,$message){if(-not $ok){throw $message}}
try { Invoke-RestMethod "$BaseUrl/api/customers" | Out-Null; throw 'Unauthorized endpoint accepted request' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 401) 'Expected 401' }
$ready=Invoke-RestMethod "$BaseUrl/health/ready";Assert ($ready.status -eq 'ready') 'Database readiness failed'
$stamp=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds(); $pass='SafePass!123'
function Register($n){Invoke-RestMethod "$BaseUrl/api/auth/register" -Method Post -ContentType application/json -SessionVariable session -Body (@{businessName="Tenant $n";email="tenant$n-$stamp@example.com";password=$pass;firstName='Test';lastName='Admin'}|ConvertTo-Json)}
$a=Register 'A'; $b=Register 'B'; Assert ($a.accessToken -and $b.accessToken) 'Registration failed'
$login=Invoke-RestMethod "$BaseUrl/api/auth/login" -Method Post -ContentType application/json -SessionVariable loginSession -Body (@{email="tenantA-$stamp@example.com";password=$pass}|ConvertTo-Json); Assert $login.accessToken 'Login failed'
if(([Uri]$BaseUrl).Scheme -eq 'https'){$renewed=Invoke-RestMethod "$BaseUrl/api/auth/refresh" -Method Post -WebSession $loginSession;Assert $renewed.accessToken 'Cookie-based token refresh failed'}else{Write-Host 'Skipping secure-cookie refresh check on HTTP. Run against the Cloudflare HTTPS URL to verify refresh.' -ForegroundColor Yellow}
$ha=@{Authorization="Bearer $($a.accessToken)"};$hb=@{Authorization="Bearer $($b.accessToken)"}
$staffEmail="staff-$stamp@example.com";$staff=Invoke-RestMethod "$BaseUrl/api/users" -Method Post -Headers $ha -ContentType application/json -Body (@{firstName='Test';lastName='Staff';email=$staffEmail;password=$pass;role='Staff'}|ConvertTo-Json);Assert ($staff.role -eq 'Staff') 'Staff creation failed'
$staffLogin=Invoke-RestMethod "$BaseUrl/api/auth/login" -Method Post -ContentType application/json -Body (@{email=$staffEmail;password=$pass}|ConvertTo-Json);$hs=@{Authorization="Bearer $($staffLogin.accessToken)"}
$departmentsA=Invoke-RestMethod "$BaseUrl/api/departments" -Headers $ha;$departmentsB=Invoke-RestMethod "$BaseUrl/api/departments" -Headers $hb;Assert ($departmentsA.Count -eq 7 -and $departmentsB.Count -eq 7) 'Default departments were not created';Assert (-not ($departmentsB.id|Where-Object {$departmentsA.id -contains $_})) 'Tenant B can see Tenant A departments'
$logisticsDepartment=$departmentsA|Where-Object {$_.code -eq 'LOGISTICS'};Assert ($logisticsDepartment.permissions.permissionCode -contains 'logistics.operate') 'Logistics permission template is missing'
$customDepartment=Invoke-RestMethod "$BaseUrl/api/departments" -Method Post -Headers $ha -ContentType application/json -Body (@{name='Client Services';code="CLIENT_$stamp";isActive=$true;permissions=@(@{permissionCode='contacts.view';minimumAccessLevel='Viewer'})}|ConvertTo-Json -Depth 5);Assert ($customDepartment.code -eq "CLIENT_$stamp") 'Custom department was not created'
$customDepartment=Invoke-RestMethod "$BaseUrl/api/departments/$($customDepartment.id)" -Method Put -Headers $ha -ContentType application/json -Body (@{name='Client Experience';code="CLIENT_$stamp";isActive=$true;permissions=@(@{permissionCode='contacts.view';minimumAccessLevel='Viewer'},@{permissionCode='contacts.manage';minimumAccessLevel='Manager'})}|ConvertTo-Json -Depth 5);Assert ($customDepartment.name -eq 'Client Experience' -and $customDepartment.permissions.Count -eq 2) 'Custom department was not updated'
$generalDepartment=$departmentsA|Where-Object {$_.code -eq 'GENERAL'}
Invoke-RestMethod "$BaseUrl/api/users/$($staff.id)/departments" -Method Put -Headers $ha -ContentType application/json -Body (@{departments=@(@{departmentId=$logisticsDepartment.id;accessLevel='Member';isPrimary=$true},@{departmentId=$generalDepartment.id;accessLevel='Viewer';isPrimary=$false})}|ConvertTo-Json -Depth 5)|Out-Null
try { Invoke-RestMethod "$BaseUrl/api/profile" -Headers $hs|Out-Null;throw 'Old token remained valid after department access changed' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 401) 'Expected immediate token revocation after department access changed' }
$staffLogin=Invoke-RestMethod "$BaseUrl/api/auth/login" -Method Post -ContentType application/json -Body (@{email=$staffEmail;password=$pass}|ConvertTo-Json);$hs=@{Authorization="Bearer $($staffLogin.accessToken)"}
$staffRecord=(Invoke-RestMethod "$BaseUrl/api/users" -Headers $ha)|Where-Object {$_.id -eq $staff.id};Assert ($staffRecord.departments.Count -eq 2 -and ($staffRecord.departments|Where-Object {$_.isPrimary}).departmentCode -eq 'LOGISTICS') 'Multiple department assignments were not saved correctly'
Invoke-RestMethod "$BaseUrl/api/departments/$($customDepartment.id)" -Method Delete -Headers $ha|Out-Null
$accessHistory=Invoke-RestMethod "$BaseUrl/api/departments/access-history" -Headers $ha;Assert ($accessHistory.Count -ge 4 -and @($accessHistory|Where-Object {$_.description -like '*department access*'}).Count -ge 1) 'Department access changes were not audited'
try { Invoke-RestMethod "$BaseUrl/api/departments/access-history" -Headers $hs|Out-Null;throw 'Staff accessed department audit history' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected department audit history Admin-only 403' }
$staffAccess=Invoke-RestMethod "$BaseUrl/api/departments/my-access" -Headers $hs;Assert ($staffAccess.permissions -contains 'logistics.view' -and $staffAccess.permissions -contains 'logistics.operate' -and -not ($staffAccess.permissions -contains 'logistics.manage')) 'Department access levels were not enforced'
$null=Invoke-RestMethod "$BaseUrl/api/logistics/resources" -Headers $hs
try { Invoke-RestMethod "$BaseUrl/api/logistics/resources" -Method Post -Headers $hs -ContentType application/json -Body (@{name='Blocked resource';type='Equipment';totalQuantity=1;status='Available'}|ConvertTo-Json)|Out-Null;throw 'Logistics member used logistics.manage' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected logistics.manage 403 for Member access' }
try { Invoke-RestMethod "$BaseUrl/api/accounting/accounts" -Headers $hs|Out-Null;throw 'Logistics member accessed accounting' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected accounting.view 403 for Logistics member' }
try { Invoke-RestMethod "$BaseUrl/api/users/$($staff.id)/departments" -Method Put -Headers $hb -ContentType application/json -Body (@{departments=@(@{departmentId=$departmentsB[0].id;accessLevel='Manager';isPrimary=$true})}|ConvertTo-Json -Depth 5)|Out-Null;throw 'Tenant B changed Tenant A department membership' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 404) 'Expected tenant-safe department assignment 404' }
$staffPhoto='https://images.example.com/staff-profile.jpg';$profile=Invoke-RestMethod "$BaseUrl/api/profile" -Method Put -Headers $hs -ContentType application/json -Body (@{profilePhotoUrl=$staffPhoto}|ConvertTo-Json);Assert ($profile.id -eq $staff.id -and $profile.profilePhotoUrl -eq $staffPhoto) 'Employee profile photo update failed'
$adminProfile=Invoke-RestMethod "$BaseUrl/api/profile" -Headers $ha;Assert ($adminProfile.id -ne $staff.id -and [string]::IsNullOrWhiteSpace([string]$adminProfile.profilePhotoUrl)) 'Employee changed another user profile'
$tenantBProfile=Invoke-RestMethod "$BaseUrl/api/profile" -Headers $hb;Assert ($tenantBProfile.id -ne $staff.id -and [string]::IsNullOrWhiteSpace([string]$tenantBProfile.profilePhotoUrl)) 'Tenant B can see Tenant A profile data'
try { Invoke-RestMethod "$BaseUrl/api/profile" -Method Put -Headers $hs -ContentType application/json -Body (@{profilePhotoUrl='http://insecure.example.com/photo.jpg'}|ConvertTo-Json)|Out-Null;throw 'Insecure profile photo URL was accepted' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 400) 'Expected insecure profile URL rejection' }
try { Invoke-RestMethod "$BaseUrl/api/users" -Headers $hs | Out-Null; throw 'Staff accessed Admin endpoint' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected Staff 403' }
try { Invoke-RestMethod "$BaseUrl/api/login-activity" -Headers $hs | Out-Null; throw 'Staff accessed login activity' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected login activity Admin-only 403' }
try { Invoke-RestMethod "$BaseUrl/api/subscription" -Headers $hs | Out-Null; throw 'Staff accessed subscription' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected subscription Admin-only 403' }
try { Invoke-RestMethod "$BaseUrl/api/subscription/cancel" -Method Post -Headers $hs | Out-Null; throw 'Staff cancelled subscription' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected cancellation Admin-only 403' }
try { Invoke-RestMethod "$BaseUrl/api/payments/payhere/notify" -Method Post -ContentType 'application/x-www-form-urlencoded' -Body 'merchant_id=invalid&order_id=invalid&payhere_amount=2500.00&payhere_currency=LKR&status_code=2&md5sig=invalid'|Out-Null;throw 'Invalid payment notification was accepted' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 401) 'Expected invalid payment signature rejection' }
$subscriptionA=Invoke-RestMethod "$BaseUrl/api/subscription" -Headers $ha;Assert ($subscriptionA.plan -eq 'Trial') 'Trial plan was not assigned';Assert ($subscriptionA.userLimit -eq 3) 'Trial user limit is incorrect';Assert ($subscriptionA.activeUsers -eq 2) 'Active subscription usage is incorrect'
$accessA=Invoke-RestMethod "$BaseUrl/api/subscription/access" -Headers $ha;Assert (-not $accessA.isReadOnly) 'Valid trial was incorrectly made read-only'
$secondStaff=Invoke-RestMethod "$BaseUrl/api/users" -Method Post -Headers $ha -ContentType application/json -Body (@{firstName='Second';lastName='Staff';email="staff2-$stamp@example.com";password=$pass;role='Staff'}|ConvertTo-Json);Assert $secondStaff.id 'Second Staff creation failed'
try { Invoke-RestMethod "$BaseUrl/api/users" -Method Post -Headers $ha -ContentType application/json -Body (@{firstName='Over';lastName='Limit';email="staff3-$stamp@example.com";password=$pass;role='Staff'}|ConvertTo-Json)|Out-Null;throw 'User limit was not enforced' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 409) 'Expected user-limit conflict' }
$activityA=Invoke-RestMethod "$BaseUrl/api/login-activity" -Headers $ha;Assert ($activityA.totalLogins -ge 2) 'Tenant A login totals were not recorded';Assert ($activityA.activeUsersLast30Days -ge 2) 'Tenant A active users were not recorded';Assert ($activityA.recentLogins.Count -ge 2) 'Recent login activity was not recorded'
$activityB=Invoke-RestMethod "$BaseUrl/api/login-activity" -Headers $hb;Assert ($activityB.totalLogins -eq 0) 'Tenant B can see Tenant A login totals';Assert (-not ($activityB.recentLogins.email -contains $staffEmail)) 'Tenant B can see Tenant A login events'
try { Invoke-RestMethod "$BaseUrl/api/settings" -Method Put -Headers $hs -ContentType application/json -Body (@{businessName='Blocked';email=$staffEmail;invoicePrefix='NO';defaultPaymentTermsDays=14;defaultTaxRate=0}|ConvertTo-Json)|Out-Null;throw 'Staff updated company settings' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected settings Admin-only 403' }
try { Invoke-RestMethod "$BaseUrl/api/users/$($staff.id)" -Method Put -Headers $hb -ContentType application/json -Body (@{firstName='Cross';lastName='Tenant';role='Staff';isActive=$true}|ConvertTo-Json)|Out-Null;throw 'Cross-tenant user was updated' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 404) 'Expected tenant-safe user 404' }
$tenantAUsers=Invoke-RestMethod "$BaseUrl/api/users" -Headers $ha;Assert ($tenantAUsers.Count -eq 3) 'Tenant A user list is incorrect'
$adminA=$tenantAUsers|Where-Object {$_.role -eq 'Admin'}
try { Invoke-RestMethod "$BaseUrl/api/users/$($adminA.id)" -Method Put -Headers $ha -ContentType application/json -Body (@{firstName=$adminA.firstName;lastName=$adminA.lastName;role='Staff';isActive=$true}|ConvertTo-Json)|Out-Null;throw 'Last Admin was demoted' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 409) 'Expected last Admin safeguard' }
$logoUrl='https://images.example.com/tenant-a-logo.png';$settings=Invoke-RestMethod "$BaseUrl/api/settings" -Method Put -Headers $ha -ContentType application/json -Body (@{businessName='Tenant A Branded';email="tenantA-$stamp@example.com";phone='0112345678';address='Colombo';taxRegistrationNumber='TAX-123';invoicePrefix='LKS';defaultPaymentTermsDays=30;defaultTaxRate=10;invoiceFooter='Thank you';paymentInstructions='Bank transfer';logoUrl=$logoUrl}|ConvertTo-Json);Assert ($settings.invoicePrefix -eq 'LKS' -and $settings.logoUrl -eq $logoUrl) 'Company settings or tenant branding update failed'
$customer=Invoke-RestMethod "$BaseUrl/api/customers" -Method Post -Headers $ha -ContentType application/json -Body (@{name='Tenant A Customer'}|ConvertTo-Json); Assert $customer.id 'Customer creation failed'
$editedCustomer=Invoke-RestMethod "$BaseUrl/api/customers/$($customer.id)" -Method Put -Headers $ha -ContentType application/json -Body (@{name='Tenant A Customer Updated';phone='0112345678';email="customer-$stamp@example.com";address='Colombo'}|ConvertTo-Json);Assert ($editedCustomer.name -eq 'Tenant A Customer Updated') 'Customer update failed'
try { Invoke-RestMethod "$BaseUrl/api/customers" -Method Post -Headers $hs -ContentType application/json -Body (@{name='Blocked Customer'}|ConvertTo-Json)|Out-Null;throw 'Staff created a customer' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected customer Admin-only 403' }
$temporaryCustomer=Invoke-RestMethod "$BaseUrl/api/customers" -Method Post -Headers $ha -ContentType application/json -Body (@{name='Temporary Customer'}|ConvertTo-Json);Invoke-RestMethod "$BaseUrl/api/customers/$($temporaryCustomer.id)" -Method Delete -Headers $ha|Out-Null;Assert (-not ((Invoke-RestMethod "$BaseUrl/api/customers" -Headers $ha).id -contains $temporaryCustomer.id)) 'Unused customer deletion failed'
$event=Invoke-RestMethod "$BaseUrl/api/events" -Method Post -Headers $ha -ContentType application/json -Body (@{customerId=$customer.id;name='Test Event';venue='Colombo';startsAt=(Get-Date).AddHours(-1).ToUniversalTime().ToString('o');endsAt=(Get-Date).AddHours(5).ToUniversalTime().ToString('o');status='Planning';budgetedRevenue=100000;budgetedCost=60000;notes='Smoke test';requireLocationForAttendance=$true;latitude=6.9271;longitude=79.8612;attendanceRadiusMeters=150;maximumLocationAccuracyMeters=50;checkInWindowMinutes=60}|ConvertTo-Json);Assert ($event.id -and $event.requireLocationForAttendance) 'Geofenced event creation failed'
$eventUpdate=@{customerId=$customer.id;name='Test Event Updated';venue='Colombo';startsAt=$event.startsAt;endsAt=$event.endsAt;status='Confirmed';budgetedRevenue=100000;budgetedCost=60000;notes='Updated';requireLocationForAttendance=$true;latitude=6.9271;longitude=79.8612;attendanceRadiusMeters=150;maximumLocationAccuracyMeters=50;checkInWindowMinutes=60};$event=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)" -Method Put -Headers $ha -ContentType application/json -Body ($eventUpdate|ConvertTo-Json);Assert ($event.name -eq 'Test Event Updated' -and $event.status -eq 'Confirmed') 'Event update failed'
try { Invoke-RestMethod "$BaseUrl/api/events/$($event.id)" -Method Put -Headers $hs -ContentType application/json -Body ($eventUpdate|ConvertTo-Json)|Out-Null;throw 'Staff updated an event' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected event update Admin-only 403' }
Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/status/Planning" -Method Patch -Headers $ha|Out-Null;$event=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/status/Confirmed" -Method Patch -Headers $ha;Assert ($event.status -eq 'Confirmed') 'Direct event status workflow failed'
try { Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/status/Completed" -Method Patch -Headers $ha|Out-Null;throw 'Invalid event status jump was accepted' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 409) 'Expected invalid event status conflict' }
try { Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/status/Planning" -Method Patch -Headers $hs|Out-Null;throw 'Staff changed event status' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected event status Admin-only 403' }
try { Invoke-RestMethod "$BaseUrl/api/customers/$($customer.id)" -Method Delete -Headers $ha|Out-Null;throw 'Customer with event history was deleted' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 409) 'Expected customer-history delete conflict' }
$eventCost=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/expenses" -Method Post -Headers $ha -ContentType application/json -Body (@{description='Transport';category='Logistics';amount=10000;expenseDate=(Get-Date -Format yyyy-MM-dd)}|ConvertTo-Json);Assert $eventCost.id 'Event expense creation failed'
$eventCost=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/expenses/$($eventCost.id)" -Method Put -Headers $ha -ContentType application/json -Body (@{description='Event transport';category='Logistics';amount=10000;expenseDate=(Get-Date -Format yyyy-MM-dd)}|ConvertTo-Json);Assert ($eventCost.description -eq 'Event transport' -and -not $eventCost.isGenerated) 'Event expense update failed'
$temporaryEventCost=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/expenses" -Method Post -Headers $ha -ContentType application/json -Body (@{description='Temporary cost';category='Testing';amount=1;expenseDate=(Get-Date -Format yyyy-MM-dd)}|ConvertTo-Json);Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/expenses/$($temporaryEventCost.id)" -Method Delete -Headers $ha|Out-Null
try { Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/expenses" -Method Post -Headers $hs -ContentType application/json -Body (@{description='Blocked';category='Testing';amount=1;expenseDate=(Get-Date -Format yyyy-MM-dd)}|ConvertTo-Json)|Out-Null;throw 'Staff created an event expense' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 403) 'Expected event expense Admin-only 403' }
$quote=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/finance/quotations" -Method Post -Headers $ha -ContentType application/json -Body (@{issueDate=(Get-Date -Format yyyy-MM-dd);validUntil=(Get-Date).AddDays(14).ToString('yyyy-MM-dd');depositRequired=30000;notes='Event package';items=@(@{description='Complete event package';quantity=1;unitPrice=100000})}|ConvertTo-Json -Depth 5);Assert $quote 'Quotation creation failed'
$finance=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/finance" -Headers $ha;$createdQuote=$finance.quotations|Select-Object -First 1;Assert ($createdQuote.total -eq 100000) 'Quotation total is incorrect'
$createdQuote=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/finance/quotations/$($createdQuote.id)" -Method Put -Headers $ha -ContentType application/json -Body (@{issueDate=(Get-Date -Format yyyy-MM-dd);validUntil=(Get-Date).AddDays(21).ToString('yyyy-MM-dd');depositRequired=30000;notes='Updated event package';items=@(@{description='Updated complete event package';quantity=1;unitPrice=100000})}|ConvertTo-Json -Depth 5);Assert ($createdQuote.status -eq 'Draft' -and $createdQuote.items[0].description -eq 'Updated complete event package') 'Draft quotation update failed'
