Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/finance/quotations/$($createdQuote.id)/status/Sent" -Method Patch -Headers $ha|Out-Null;Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/finance/quotations/$($createdQuote.id)/status/Accepted" -Method Patch -Headers $ha|Out-Null
try { Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/finance/quotations/$($createdQuote.id)" -Method Delete -Headers $ha|Out-Null;throw 'Sent quotation was deleted' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 409) 'Expected non-draft quotation delete conflict' }
