Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/finance/invoices/$($converted.id)/payments" -Method Post -Headers $ha -ContentType application/json -Body (@{amount=30000;paymentDate=(Get-Date -Format yyyy-MM-dd);method='Bank transfer';reference='DEP-1';isDeposit=$true}|ConvertTo-Json)|Out-Null
