Invoke-RestMethod "$BaseUrl/api/purchase-orders/$($purchase.id)/status/Draft" -Method Patch -Headers $ha|Out-Null
Invoke-RestMethod "$BaseUrl/api/purchase-orders/$($purchase.id)/status/Ordered" -Method Patch -Headers $ha|Out-Null
Invoke-RestMethod "$BaseUrl/api/purchase-orders/$($purchase.id)/status/Received" -Method Patch -Headers $ha|Out-Null
try { Invoke-RestMethod "$BaseUrl/api/purchase-orders/$($purchase.id)/status/Draft" -Method Patch -Headers $ha|Out-Null;throw 'Received order was revised' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 409) 'Expected received-order revision conflict' }
$tenantBOrders=Invoke-RestMethod "$BaseUrl/api/purchase-orders" -Headers $hb;Assert ($tenantBOrders.Count -eq 0) 'Tenant B can see Tenant A purchase orders'
$expectedEventCost=15000+$labourCost;$eventSeen=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)" -Headers $ha;Assert ($eventSeen.actualCost -eq $expectedEventCost) 'Event actual cost is incorrect';Assert ($eventSeen.forecastProfit -eq (100000-$expectedEventCost)) 'Event forecast profit is incorrect'
