$eventProfit=Invoke-RestMethod "$BaseUrl/api/accounting/profit-loss?eventId=$($event.id)" -Headers $ha;Assert ($eventProfit.revenue -eq 100000 -and $eventProfit.expenses -eq $expectedEventCost -and $eventProfit.netProfit -eq (100000-$expectedEventCost)) "Event profit and loss is incorrect. Revenue=$($eventProfit.revenue), Expenses=$($eventProfit.expenses), Net=$($eventProfit.netProfit), Range=$($eventProfit.from)..$($eventProfit.to)"
