Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/logistics/allocations/$($allocation.id)/return" -Method Post -Headers $ha -ContentType application/json -Body (@{returnedQuantity=6;damagedQuantity=1;missingQuantity=0}|ConvertTo-Json)|Out-Null
$returnedLogistics=Invoke-RestMethod "$BaseUrl/api/events/$($event.id)/logistics" -Headers $ha;$returnedAllocation=$returnedLogistics.allocations|Where-Object id -eq $allocation.id;Assert ($returnedAllocation.status -eq 'Returned' -and $returnedAllocation.returnedQuantity -eq 6 -and $returnedAllocation.damagedQuantity -eq 1) 'Damaged resource return was not recorded correctly'
