try { Invoke-RestMethod "$BaseUrl/api/events/$($event.id)" -Headers $hb|Out-Null;throw 'Cross-tenant event was exposed' } catch { Assert ($_.Exception.Response.StatusCode.value__ -eq 404) 'Expected tenant-safe event 404' }
